const num = v => (v === '' || v == null || isNaN(Number(v))) ? null : Number(v);
const txt = v => (v === '' || v == null) ? null : String(v);

const regs = $input.first().json.registros || [];
// So transmissores cujo nome comeca com "OLT" (padrao de nomes do IXC)
const rows = regs
  .filter(r => /^OLT/i.test(r.descricao || ''))
  .map(r => ({
    id: num(r.id),
    descricao: txt(r.descricao),
    id_pop: num(r.id_pop),
    fabricante_modelo: txt(r.fabricante_modelo),
    busca_potencia: txt(r.busca_potencia),
    ativo: txt(r.ativo),
  }));
// Protecao: sem dados nao grava (evita apagar a tabela por falha na API)
if (!rows.length) throw new Error('Nenhuma OLT retornada pelo IXC - sincronizacao abortada');
return [{ json: { rows, total: rows.length } }];

const total = Number($input.first().json.total || 0);
if (!total) throw new Error('IXC retornou total de CTOs = 0 - sincronizacao abortada');
const rp = 1000;
const paginas = Math.ceil(total / rp);
return Array.from({ length: paginas }, (_, i) => ({ json: { page: i + 1, rp, total } }));

const num = v => (v === '' || v == null || isNaN(Number(v))) ? null : Number(v);
const txt = v => (v === '' || v == null) ? null : String(v);

const total = Number($('Paginas CTOs').first().json.total);
const porId = new Map();
for (const it of $input.all()) {
  for (const r of (it.json.registros || [])) {
    const lat = num(r.latitude), lon = num(r.longitude);
    porId.set(num(r.id), {
      id: num(r.id),
      descricao: txt(r.descricao),
      id_transmissor: num(r.id_transmissor),
      id_projeto: num(r.id_projeto),
      capacidade: num(r.capacidade),
      status: txt(r.status),
      tipo: txt(r.tipo),
      latitude: (lat !== null && Math.abs(lat) <= 90) ? lat : null,
      longitude: (lon !== null && Math.abs(lon) <= 180) ? lon : null,
    });
  }
}
const rows = [...porId.values()].filter(r => r.id !== null);
// Protecao: so grava se veio a base completa
if (rows.length < total) throw new Error(`CTOs incompletas: ${rows.length} de ${total} - sincronizacao abortada`);
return [{ json: { rows, total: rows.length } }];
